"""Stream upload tests use generated bytes and temporary files only.

Run without additional dependencies: python tests_gui/test_upload_io.py
"""
from __future__ import annotations

import io
from pathlib import Path
import stat
import sys
import tempfile
import tracemalloc
import unittest
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from gui import upload_io
from gui.table_import import InputError


class GeneratedStream:
    """Generate each read on demand, never allocate the entire upload."""

    def __init__(self, size, short_reads=None, error=None):
        self.remaining = size
        self.short_reads = short_reads
        self.error = error
        self.requests = []

    def read(self, size):
        if not 0 < size <= upload_io.CHUNK_BYTES:
            raise AssertionError(f'unbounded read: {size}')
        self.requests.append(size)
        if self.error is not None and len(self.requests) == 2:
            raise self.error
        count = min(size, self.remaining)
        if self.short_reads is not None:
            count = min(count, self.short_reads)
        self.remaining -= count
        return b'x' * count


class UploadLimitTests(unittest.TestCase):
    def test_default_is_one_hundred_mib(self):
        self.assertEqual(upload_io.choose_upload_limit(), 100 * 1024 * 1024)
        self.assertEqual(upload_io.DEFAULT_UPLOAD_BYTES, 100 * 1024 * 1024)

    def test_startup_integer_and_decimal_string_values(self):
        for value in [1, 25, 100, 200, '1', '100', '200', ' 100 ']:
            with self.subTest(value=value):
                self.assertEqual(upload_io.choose_upload_limit(value), int(value) * upload_io.MIB)

    def test_invalid_startup_values_do_not_truncate_or_coerce(self):
        for value in [None, True, False, 0, -1, 201, 100.0, 1.5, float('nan'),
                      float('inf'), '', '0', '-1', '+1', '201', '1.5', '100.0',
                      'NaN', 'Infinity', '1e2', '１', '1_0', [], {}]:
            with self.subTest(value=value), self.assertRaises(InputError):
                upload_io.choose_upload_limit(value)


class ReceiveUploadTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory(prefix='poi-upload-qa-')
        self.directory = Path(self.temporary.name)

    def tearDown(self):
        self.temporary.cleanup()

    def receive(self, stream, length, max_bytes=upload_io.DEFAULT_UPLOAD_BYTES):
        return upload_io.receive_upload(stream, length, self.directory, max_bytes)

    def test_binary_bytes_preserved_without_decoding(self):
        payload = b'PK\x03\x04\x00\xff\xfe\x80\r\n\x00,\xef\xbb\xbf'
        path = self.receive(io.BytesIO(payload), str(len(payload)))
        self.assertEqual(path.read_bytes(), payload)
        self.assertEqual(path.parent, self.directory)
        self.assertTrue(stat.S_ISREG(path.stat().st_mode))
        self.assertFalse(path.is_symlink())
        self.assertTrue(path.name.startswith('upload-'))
        self.assertEqual(path.suffix, '.tmp')

    def test_random_names_preserve_existing_files(self):
        original = self.directory / 'original.xlsx'
        original.write_bytes(b'keep original')
        first = self.receive(io.BytesIO(b'one'), 3)
        second = self.receive(io.BytesIO(b'two'), 3)
        self.assertNotEqual(first, second)
        self.assertEqual(first.read_bytes(), b'one')
        self.assertEqual(second.read_bytes(), b'two')
        self.assertEqual(original.read_bytes(), b'keep original')

    def test_creates_only_provided_directory(self):
        destination = self.directory / 'inputs'
        path = upload_io.receive_upload(io.BytesIO(b'abc'), 3, destination, 3)
        self.assertEqual(path.parent, destination)
        self.assertEqual(path.read_bytes(), b'abc')

    def test_reads_exact_length_without_consuming_following_bytes(self):
        stream = io.BytesIO(b'abcNEXT')
        path = self.receive(stream, 3, 3)
        self.assertEqual(path.read_bytes(), b'abc')
        self.assertEqual(stream.read(), b'NEXT')

    def test_short_reads_are_supported(self):
        stream = GeneratedStream(100, short_reads=7)
        path = self.receive(stream, 100)
        self.assertEqual(path.read_bytes(), b'x' * 100)
        self.assertEqual(stream.remaining, 0)
        self.assertGreater(len(stream.requests), 1)

    def test_default_accepts_exactly_one_hundred_mib_with_bounded_memory(self):
        stream = GeneratedStream(upload_io.DEFAULT_UPLOAD_BYTES)
        tracemalloc.start()
        try:
            path = self.receive(stream, upload_io.DEFAULT_UPLOAD_BYTES)
            _, peak = tracemalloc.get_traced_memory()
        finally:
            tracemalloc.stop()
        self.assertEqual(path.stat().st_size, upload_io.DEFAULT_UPLOAD_BYTES)
        self.assertEqual(len(stream.requests), 100)
        self.assertEqual(max(stream.requests), 1024 * 1024)
        self.assertEqual(stream.remaining, 0)
        # Two adjacent 1 MiB chunks can coexist during Python assignment.
        self.assertLess(peak, 4 * 1024 * 1024)

    def test_last_read_is_capped_to_remaining_bytes(self):
        size = 2 * upload_io.CHUNK_BYTES + 17
        stream = GeneratedStream(size)
        path = self.receive(stream, size)
        self.assertEqual(stream.requests, [upload_io.CHUNK_BYTES, upload_io.CHUNK_BYTES, 17])
        self.assertEqual(path.stat().st_size, size)

    def test_invalid_lengths_reject_before_read_or_file_creation(self):
        invalid = [None, '', ' ', True, False, 0, -1, 1.0, 1.5, float('nan'),
                   float('inf'), '0', '-1', '+1', '1.0', '1e2', '1_0', '１',
                   '1,1', '1\x00', b'1', [], {}, '9' * 5000]
        for length in invalid:
            stream = GeneratedStream(1)
            with self.subTest(length=str(length)[:30]), self.assertRaises(InputError):
                self.receive(stream, length)
            self.assertEqual(stream.requests, [])
            self.assertEqual(list(self.directory.iterdir()), [])

    def test_oversize_rejects_before_read_or_file_creation(self):
        for limit in [1, upload_io.DEFAULT_UPLOAD_BYTES, upload_io.MAX_UPLOAD_BYTES]:
            stream = GeneratedStream(limit + 1)
            with self.subTest(limit=limit), self.assertRaisesRegex(InputError, '上限'):
                self.receive(stream, str(limit + 1), limit)
            self.assertEqual(stream.requests, [])
            self.assertEqual(list(self.directory.iterdir()), [])

    def test_invalid_limits_reject_before_read_or_file_creation(self):
        for limit in [None, True, 0, -1, 1.5, float('nan'), 'NaN']:
            stream = GeneratedStream(1)
            with self.subTest(limit=limit), self.assertRaises(InputError):
                self.receive(stream, 1, limit)
            self.assertEqual(stream.requests, [])
            self.assertEqual(list(self.directory.iterdir()), [])

    def test_empty_or_truncated_body_removes_partial_file(self):
        original = self.directory / 'original.csv'
        original.write_bytes(b'keep')
        for available in [0, 7, upload_io.CHUNK_BYTES]:
            stream = GeneratedStream(available)
            with self.subTest(available=available), self.assertRaisesRegex(InputError, '上传未完成'):
                self.receive(stream, available + 1)
            self.assertEqual(list(self.directory.iterdir()), [original])
            self.assertEqual(original.read_bytes(), b'keep')

    def test_stream_exception_removes_partial_file(self):
        for error in [OSError('disconnected'), RuntimeError('read failed'), KeyboardInterrupt()]:
            stream = GeneratedStream(2 * upload_io.CHUNK_BYTES, error=error)
            with self.subTest(error=type(error)), self.assertRaises(type(error)):
                self.receive(stream, 2 * upload_io.CHUNK_BYTES)
            self.assertEqual(list(self.directory.iterdir()), [])

    def test_nonbinary_or_overlong_reads_remove_partial_file(self):
        for chunk in ['text', None, memoryview(b'x'), b'too much']:
            stream = unittest.mock.Mock()
            stream.read.return_value = chunk
            with self.subTest(chunk=chunk), self.assertRaises(InputError):
                self.receive(stream, 1)
            self.assertEqual(list(self.directory.iterdir()), [])

    def test_write_failure_removes_partial_file(self):
        factory = tempfile.NamedTemporaryFile

        class FailingWriter:
            def __init__(self, **kwargs):
                self.file = factory(**kwargs)
                self.name = self.file.name

            def __enter__(self):
                return self

            def __exit__(self, *args):
                self.file.close()

            def write(self, data):
                self.file.write(data[:1])
                raise OSError('disk full')

        with patch.object(upload_io.tempfile, 'NamedTemporaryFile', FailingWriter):
            with self.assertRaisesRegex(OSError, 'disk full'):
                self.receive(io.BytesIO(b'abc'), 3)
        self.assertEqual(list(self.directory.iterdir()), [])


if __name__ == '__main__':
    unittest.main()
